/** Only claim relations are read here; authority, order revisions and payment evidence use public ports. */
@Service @Profile("db")
public final class JdbcReturnQueries implements ReturnQueries {
 @org.springframework.beans.factory.annotation.Autowired private com.example.marketplace.order.api.ExchangeApplications exchangeApplications;
 private enum Actor { OWNER, SELLER, SUPPORT }
 private record Scope(Actor actor,String number,UUID seller,OrderQueries.Authority authority,UUID orderId,long revision,ReturnApplications.Eligibility eligibility) { }
 private final NamedParameterJdbcTemplate jdbc;private final OrderQueries queries;private final Orders orders;private final com.example.marketplace.order.api.AftercareSettlements aftercare;private final ReturnApplications applications;private final CurrentSupport currentSupport;private final Refunds refunds;private final com.example.marketplace.claim.api.FinancialIntents intents;private final ReturnCommands commands;private final TransactionTemplate tx;
 public JdbcReturnQueries(NamedParameterJdbcTemplate jdbc,OrderQueries queries,Orders orders,ReturnApplications applications,CurrentSupport currentSupport,Refunds refunds,ReturnCommands commands,com.example.marketplace.order.api.AftercareSettlements aftercare,com.example.marketplace.claim.api.FinancialIntents intents,PlatformTransactionManager manager) { this.jdbc=jdbc;this.queries=queries;this.orders=orders;this.applications=applications;this.currentSupport=currentSupport;this.refunds=refunds;this.commands=commands;this.aftercare=aftercare;this.intents=intents;this.tx=new TransactionTemplate(manager); }
 @Override public Page owner(String number,OrderQueries.Authority authority,int size,String cursor) { return tx.execute(t->page(scope(Actor.OWNER,number,null,authority),size,cursor)); }
 @Override public Page seller(UUID seller,OrderQueries.Authority authority,int size,String cursor) { return tx.execute(t->page(scope(Actor.SELLER,null,seller,authority),size,cursor)); }
 @Override public Page support(String number,OrderQueries.Authority authority,int size,String cursor) { return tx.execute(t->page(scope(Actor.SUPPORT,number,null,authority),size,cursor)); }
 @Override public Detail owner(String number,UUID id,OrderQueries.Authority authority) { return tx.execute(t->detail(scope(Actor.OWNER,number,null,authority),id)); }
 @Override public Detail seller(UUID seller,UUID id,OrderQueries.Authority authority) { return tx.execute(t->detail(scope(Actor.SELLER,null,seller,authority),id)); }
 @Override public Detail support(String number,UUID id,OrderQueries.Authority authority) { return tx.execute(t->detail(scope(Actor.SUPPORT,number,null,authority),id)); }
 private Scope scope(Actor actor,String number,UUID seller,OrderQueries.Authority authority) {
  UUID order;if(actor==Actor.OWNER) { order=queries.lockOwned(number,authority).id(); }else if(actor==Actor.SELLER) { var own=queries.lockSellerOrder(seller,authority);number=own.orderNumber();order=orders.lock(number).id(); }else { currentSupport.require(authority);order=orders.lock(number).id(); }
  var current=applications.current(order);var eligibility=actor==Actor.OWNER?applications.eligibility(number,authority):null;return new Scope(actor,number,seller,authority,order,current.revision(),eligibility);
 }
 private void finalAuthority(Scope scope) {
  switch(scope.actor()) { case OWNER->queries.lockOwned(scope.number(),scope.authority());case SELLER->queries.lockSellerOrder(scope.seller(),scope.authority());case SUPPORT->currentSupport.require(scope.authority()); }
 }
 private String scopeKey(Scope scope) {
  var a=scope.authority();return ReturnFeeQuoting.hash("RETURN_HISTORY_ALL_V1|"+scope.actor()+"|"+scope.orderId()+"|"+scope.seller()+"|"+a.member()+"|"+a.browser()+"|"+a.version()+"|"+a.guestToken());
 }
 private Page page(Scope scope,int size,String cursor) {
  if(size<1||size>50) { throw new OrderRejected(400); }var p=new MapSqlParameterSource("order",scope.orderId()).addValue("seller",scope.seller()).addValue("limit",size+1);String after="";String key=scopeKey(scope);
  if(cursor!=null&&!cursor.isEmpty()) { try { if(cursor.length()>1000) { throw new IllegalArgumentException(); }var parts=new String(Base64.getUrlDecoder().decode(cursor),StandardCharsets.UTF_8).split("\\|",-1);if(parts.length!=3||!parts[0].equals(key)) { throw new IllegalArgumentException(); }p.addValue("at",Timestamp.from(Instant.parse(parts[1]))).addValue("id",UUID.fromString(parts[2]));after=" AND (requested_at,id)<(:at,:id)"; }catch(IllegalArgumentException invalid) { throw new OrderRejected(400); } }
  var rows=jdbc.queryForList("SELECT * FROM marketplace.claim_return_request WHERE order_id=:order"+(scope.seller()==null?"":" AND seller_order_id=:seller")+after+" ORDER BY requested_at DESC,id DESC LIMIT :limit FOR UPDATE",p);boolean more=rows.size()>size;var shown=rows.stream().limit(size).toList();var entries=shown.stream().map(row->{var progress=commands.progress(row);return new Summary(progress.accepted().returnId(),progress.state(),progress.version(),progress.accepted().requestedAt(),progress.accepted().units());}).toList();String next=null;if(more) { var last=shown.getLast();next=Base64.getUrlEncoder().withoutPadding().encodeToString((key+"|"+((Timestamp)last.get("requested_at")).toInstant()+"|"+last.get("id")).getBytes(StandardCharsets.UTF_8)); }
  var shipping=new java.util.ArrayList<Shipping>();for(var seller:orders.find(scope.number()).sellers().stream().filter(v->scope.seller()==null||scope.seller().equals(v.id())).sorted(java.util.Comparator.comparing(v->v.id().toString())).toList()) { var current=shipping(aftercare.lockAftercare(seller.id()));if(current.originIntentId()!=null) { shipping.add(current); } }finalAuthority(scope);return new Page(entries,next,scope.revision(),scope.eligibility(),shipping);
 }
 private Detail detail(Scope scope,UUID id) {
  if(id==null) { throw new OrderRejected(404); }var routes=jdbc.queryForList("SELECT order_id,seller_order_id FROM marketplace.claim_return_request WHERE id=:id",Map.of("id",id));if(routes.size()!=1||!scope.orderId().equals(routes.getFirst().get("order_id"))||scope.seller()!=null&&!scope.seller().equals(routes.getFirst().get("seller_order_id"))) { throw new OrderRejected(404); }
  var view=aftercare.lockAftercare((UUID)routes.getFirst().get("seller_order_id"));var recorded=applications.lockRecorded(id);var app=recorded.application();var row=jdbc.queryForMap("SELECT * FROM marketplace.claim_return_request WHERE id=:id FOR UPDATE",Map.of("id",id));if(!app.orderId().equals(scope.orderId())||!app.sellerOrderId().equals(row.get("seller_order_id"))||!app.holdId().equals(row.get("hold_id"))||!app.causeId().equals(row.get("cause_id"))) { throw new OrderRejected(409); }
  var progress=commands.progress(row);var item=item(id,app);var shipping=shipping(view);var actions=new java.util.ArrayList<String>();
  if(scope.actor()==Actor.OWNER) { if(progress.state().equals("REQUESTED")) { actions.add("WITHDRAW"); }if(progress.state().equals("AWAITING_CONSENT")) { actions.add("QUOTE");actions.add("CONSENT"); } }
  if(scope.actor()==Actor.SELLER) { if(progress.state().equals("REQUESTED")) { actions.add("APPROVE");actions.add("REJECT"); }if(List.of("APPROVED","COLLECTING","REVIEW_REQUIRED").contains(progress.state())&&progress.physical().stream().anyMatch(u->!u.collection().equals("RECEIVED")&&u.inspection().equals("NOT_INSPECTED"))) { actions.add("RECEIVE"); }if(progress.physical().stream().anyMatch(u->u.collection().equals("RECEIVED")&&u.inspection().equals("NOT_INSPECTED"))) { actions.add("INSPECT"); } }
  if(scope.actor()==Actor.SUPPORT) { if(progress.state().equals("REVIEW_REQUIRED")&&item.state().equals("FAILED")&&item.assessmentState().equals("BOUND")) { actions.add("ITEM_RETRY"); }if(progress.state().equals("REVIEW_REQUIRED")&&item.state().equals("UNKNOWN")&&item.assessmentState().equals("BOUND")) { actions.add("ITEM_QUERY"); }if(shipping.supportActions().contains("RETRY")) { actions.add("SHIPPING_RETRY"); }if(shipping.supportActions().contains("QUERY")) { actions.add("SHIPPING_QUERY"); } }
  var original=originalUnits(scope,app);var current=applications.current(scope.orderId());finalAuthority(scope);return new Detail(progress,current.revision(),current.orderState(),original,item,shipping,actions);
 }
 private List<OriginalUnit> originalUnits(Scope scope,ReturnApplications.Accepted app) {
  var saved=orders.find(scope.number());if(!saved.id().equals(app.orderId())) { throw new OrderRejected(409); }var seller=saved.sellers().stream().filter(s->s.id().equals(app.sellerOrderId())).findFirst().orElseThrow(()->new OrderRejected(409));
  return app.source().units().stream().map(u->{var item=seller.items().stream().filter(i->i.id().equals(u.itemId())).findFirst().orElseThrow(()->new OrderRejected(409));var line=saved.quote().stores().stream().flatMap(s->s.lines().stream()).filter(l->l.skuId().equals(item.skuId())).findFirst().orElseThrow(()->new OrderRejected(409));return new OriginalUnit(app.sellerOrderId(),u.itemId(),u.ordinal(),line.title(),Long.toString(u.net()),u.returnPolicy());}).toList();
 }
 private Item item(UUID id,ReturnApplications.Accepted app) {
  var rows=jdbc.queryForList("SELECT a.id,a.state,a.refund,a.increment,a.additional_due,a.quote_fingerprint,b.attempt_id FROM marketplace.claim_return_financial_consent c JOIN marketplace.claim_fee_assessment a ON a.id=c.assessment_id JOIN marketplace.claim_fee_binding b ON b.assessment_id=a.id WHERE c.return_id=:id",Map.of("id",id));
  if(rows.isEmpty()) { return new Item("ITEM","NONE",null,null,0,0,"0","0","0",null,null,"NONE"); }if(rows.size()!=1) { throw new OrderRejected(409); }var row=rows.getFirst();var actual=refunds.get((UUID)row.get("attempt_id"));if(!actual.claimId().equals(id)||!actual.orderId().equals(app.orderId())||!actual.sellerOrderId().equals(app.sellerOrderId())||!actual.purpose().equals("ITEM")||actual.amount()!=((Number)row.get("refund")).longValue()||!refunds.originalReference(actual.id()).equals(row.get("quote_fingerprint"))) { throw new OrderRejected(409); }
  return new Item("ITEM",actual.state(),(UUID)row.get("id"),actual.id(),actual.sequence(),actual.version(),Long.toString(actual.amount()),row.get("increment").toString(),row.get("additional_due").toString(),actual.resultReference(),actual.resultAt(),row.get("state").toString());
 }
 Shipping shipping(com.example.marketplace.order.api.AftercareSettlements.AftercareView view) {
  var decisions=jdbc.queryForList("SELECT d.* FROM marketplace.claim_seller_shipping_current c JOIN marketplace.claim_seller_shipping_decision d ON d.id=c.decision_id WHERE c.seller_order_id=:seller",Map.of("seller",view.sellerOrderId()));if(decisions.size()>1) { throw new OrderRejected(409); }
  var rows=jdbc.queryForList("SELECT * FROM marketplace.claim_shipping_obligation WHERE seller_order_id=:seller FOR UPDATE",Map.of("seller",view.sellerOrderId()));if(rows.size()>1) { throw new OrderRejected(409); }
  String decision=decisions.isEmpty()?"UNDECIDED":decisions.getFirst().get("state").toString(),reason=decisions.isEmpty()?"AWAITING_ORIGINAL_UNIT_FACTS":decisions.getFirst().get("reason").toString();long decisionRevision=decisions.isEmpty()?0:((Number)decisions.getFirst().get("revision")).longValue();
  if(rows.isEmpty()) { return new Shipping("SHIPPING",decision,reason,decisionRevision,0,"NONE",null,0,0,decisions.isEmpty()?"0":decisions.getFirst().get("amount").toString(),null,null,"NONE",view.sellerOrderId(),"NONE",null,"NONE","NONE",0,List.of()); }
  var obligation=rows.getFirst();var intent=intents.lock((UUID)obligation.get("claim_id"));if(!view.orderId().equals(obligation.get("order_id"))||!intent.orderId().equals(view.orderId())||!intent.sellerOrderId().equals(view.sellerOrderId())) { throw new OrderRejected(409); }
  var workflow=shippingWorkflow(view,intent);var actual=refunds.get((UUID)obligation.get("refund_attempt_id"));var original=refunds.original(view.orderId());
  if(!actual.orderId().equals(view.orderId())||!actual.sellerOrderId().equals(view.sellerOrderId())||!actual.purpose().equals("SHIPPING")||!actual.claimId().equals(intent.id())||actual.amount()!=((Number)obligation.get("amount")).longValue()||!actual.paymentId().equals(original.paymentId())||original.amount()!=view.originalPaidAmount()||!original.mode().equals(view.mode())||view.recordedPaymentIds().stream().anyMatch(payment->!payment.equals(actual.paymentId()))||actual.amount()!=view.originalShipping()||!refunds.originalReference(actual.id()).equals(view.quoteFingerprint())) { throw new OrderRejected(409); }
  var p=new MapSqlParameterSource("attempt",actual.id()).addValue("intent",intent.id()).addValue("order",view.orderId()).addValue("seller",view.sellerOrderId()).addValue("kind",intent.kind()).addValue("payment",actual.paymentId()).addValue("amount",actual.amount()).addValue("reference",view.quoteFingerprint());
  if(jdbc.queryForObject("SELECT count(*) FROM marketplace.claim_financial_refund_binding WHERE attempt_id=:attempt AND intent_id=:intent AND order_id=:order AND seller_order_id=:seller AND intent_kind=:kind AND purpose='SHIPPING' AND payment_id=:payment AND amount=:amount AND original_reference=:reference",p,Integer.class)!=1) { throw new OrderRejected(409); }
  boolean returned=intent.kind().equals("RETURN"),exchanged=intent.kind().equals("EXCHANGE_REFUND"),physical=returned||exchanged;if(physical&&jdbc.queryForObject("SELECT count(*) FROM marketplace.claim_concrete_shipping_binding WHERE attempt_id=:attempt AND intent_id=:intent AND kind=:kind AND order_id=:order AND seller_order_id=:seller AND payment_id=:payment AND amount=:amount AND original_reference=:reference",p,Integer.class)!=1) { throw new OrderRejected(409); }
  if(decisions.isEmpty()) { if(physical) { throw new OrderRejected(409); }decision="REFUND_REQUIRED";reason="ALL_UNSENT_CANCELED"; }else if(!decision.equals("REFUND_REQUIRED")) { throw new OrderRejected(409); }
  long revision=((Number)obligation.get("version")).longValue(),commandRevision=physical?revision:((Number)workflow.get("version")).longValue();var actions=new java.util.ArrayList<String>();boolean ready=applications.current(view.orderId()).orderState().equals("PAID")&&(physical?List.of("REFUND_PENDING","COMPLETED","REFUNDED").contains(workflow.get("state")):workflow.get("state").equals("REVIEW_REQUIRED"));
  if(ready&&actual.state().equals("FAILED")&&(!physical||obligation.get("state").equals("FAILED"))) { actions.add("RETRY"); }if(ready&&actual.state().equals("UNKNOWN")&&(!physical||obligation.get("state").equals("UNKNOWN"))) { actions.add("QUERY"); }
  return new Shipping("SHIPPING",decision,reason,decisionRevision,revision,obligation.get("state").toString(),actual.id(),actual.sequence(),actual.version(),Long.toString(actual.amount()),actual.resultReference(),actual.resultAt(),actual.state(),view.sellerOrderId(),intent.kind(),intent.id(),returned?"RETURN_SHIPPING":exchanged?"EXCHANGE_REFUND_SHIPPING":"CANCEL_SHIPPING",physical?"SHIPPING_OBLIGATION":"CANCEL_CLAIM",commandRevision,actions);
 }
 private Map<String,Object> shippingWorkflow(com.example.marketplace.order.api.AftercareSettlements.AftercareView view,com.example.marketplace.claim.api.FinancialIntents.Reference intent) {
  if(intent.kind().equals("RETURN")) {
   var recorded=applications.lockRecorded(intent.id());var app=recorded.application();var canonical=app.source().units().stream().map(u->new com.example.marketplace.order.api.OrderConfirmations.Unit(u.itemId(),u.ordinal())).sorted(java.util.Comparator.comparing((com.example.marketplace.order.api.OrderConfirmations.Unit u)->u.itemId().toString()).thenComparingInt(com.example.marketplace.order.api.OrderConfirmations.Unit::ordinal)).toList();
   var row=jdbc.queryForMap("SELECT * FROM marketplace.claim_return_request WHERE id=:id FOR UPDATE",Map.of("id",intent.id()));if(recorded.holdState()==ReturnApplications.RecordedHoldState.RELEASED||!app.orderId().equals(view.orderId())||!app.sellerOrderId().equals(view.sellerOrderId())||!app.holdId().equals(intent.holdId())||!app.causeId().equals(intent.causeId())||!canonical.equals(intent.units())||!row.get("hold_id").equals(intent.holdId())||!row.get("cause_id").equals(intent.causeId())||jdbc.queryForObject("SELECT count(*) FROM marketplace.claim_return_item_ready WHERE return_id=:id AND order_id=:order AND seller_order_id=:seller",Map.of("id",intent.id(),"order",view.orderId(),"seller",view.sellerOrderId()),Integer.class)!=1) { throw new OrderRejected(409); }return row;
  }
  if(intent.kind().equals("EXCHANGE_REFUND")) { var app=exchangeApplications.lockRecorded(intent.id());var canonical=app.units().stream().map(u->new com.example.marketplace.order.api.OrderConfirmations.Unit(u.itemId(),u.ordinal())).sorted(java.util.Comparator.comparing((com.example.marketplace.order.api.OrderConfirmations.Unit u)->u.itemId().toString()).thenComparingInt(com.example.marketplace.order.api.OrderConfirmations.Unit::ordinal)).toList();var row=jdbc.queryForMap("SELECT * FROM marketplace.claim_exchange_request WHERE id=:id FOR UPDATE",Map.of("id",intent.id()));if(!app.orderId().equals(view.orderId())||!app.sellerOrderId().equals(view.sellerOrderId())||!app.holdId().equals(intent.holdId())||!app.causeId().equals(intent.causeId())||!canonical.equals(intent.units())||!row.get("hold_id").equals(intent.holdId())||!row.get("cause_id").equals(intent.causeId())||jdbc.queryForObject("SELECT count(*) FROM marketplace.claim_exchange_refund_item_ready WHERE exchange_id=:id AND order_id=:order AND seller_order_id=:seller",Map.of("id",intent.id(),"order",view.orderId(),"seller",view.sellerOrderId()),Integer.class)!=1){throw new OrderRejected(409);}return row; }
  if(!intent.kind().equals("CANCEL")) { throw new OrderRejected(409); }var row=jdbc.queryForMap("SELECT * FROM marketplace.claim WHERE id=:id FOR UPDATE",Map.of("id",intent.id()));var units=jdbc.query("SELECT item_id,ordinal FROM marketplace.claim_unit WHERE claim_id=:id ORDER BY item_id::text,ordinal",Map.of("id",intent.id()),(r,n)->new com.example.marketplace.order.api.OrderConfirmations.Unit(r.getObject(1,UUID.class),r.getInt(2)));if(!row.get("order_id").equals(view.orderId())||!row.get("seller_order_id").equals(view.sellerOrderId())||!row.get("hold_id").equals(intent.holdId())||!intent.causeId().equals(intent.id())||!units.equals(intent.units())) { throw new OrderRejected(409); }return row;
 }
}
